const STORAGE_KEY="tts-prototype-04";
const emptyState=()=>({startingPoint:"",mode:"thinking",events:[],thinkingState:{resonances:[],irritations:[],theological_tensions:[],questions:[],emerging_testimonies:[],unresolved:[]},pendingCandidates:[],suggestion:null,readiness:"not_yet",conversationDynamics:{dominant_theme:"",movement:"medium",risk:"none",next_move:"deepen",note:""},threshold:{}});
let state=load()||emptyState(),busy=false;const $=id=>document.getElementById(id);
const labels={human:"DU / TEAM",companion:"COMPANION",bible:"BIBEL / THEOLOGIE",liturgy:"LITURGIE / PRAXIS",outside:"AUSSENBLICK"};
const buckets={resonances:"Resonanzen",irritations:"Irritationen",theological_tensions:"Theologische Spannungen",questions:"Offene Fragen",emerging_testimonies:"Vorl?ufige Zeugnisse",unresolved:"Noch offen"};
const typeToBucket={resonance:"resonances",irritation:"irritations",theological_tension:"theological_tensions",question:"questions",emerging_testimony:"emerging_testimonies",unresolved:"unresolved"};
const moveLabels={deepen:"vertiefen",differentiate:"unterscheiden",contrast:"Kontrast ?ffnen",contextualize:"Kontext weiten",resource:"Ressourcen suchen",condense:"verdichten",park:"Spur parken",threshold:"Schwelle pr?fen"};
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}function load(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY))}catch{return null}}function esc(s=""){return String(s).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;")}
function render(){
$("startPanel").classList.toggle("hidden",!!state.startingPoint);$("thinkingView").classList.toggle("hidden",!state.startingPoint||state.mode!=="thinking");$("thresholdView").classList.toggle("hidden",state.mode!=="threshold");$("modeBadge").textContent=state.mode==="thinking"?"DENKRAUM":"SCHWELLE";
$("stream").innerHTML=state.events.map(e=>`<article class="entry ${e.author==="human"?"human":e.author==="companion"?"companion":"perspective"}"><div class="meta">${esc(labels[e.author]||e.author)}</div><p>${esc(e.text)}</p></article>`).join("");
$("stateGroups").innerHTML=Object.entries(buckets).map(([k,l])=>`<section class="state-group"><h3>${l}</h3>${state.thinkingState[k]?.length?`<ul>${state.thinkingState[k].map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:`<div class="empty">Noch nichts festgehalten.</div>`}</section>`).join("");
$("candidateArea").classList.toggle("hidden",!state.pendingCandidates.length);$("candidateList").innerHTML=state.pendingCandidates.map((c,i)=>`<div class="candidate"><p><strong>${esc(buckets[typeToBucket[c.type]]||c.type)}:</strong> ${esc(c.text)}</p><button data-i="${i}" data-a="accept">Festhalten</button> <button class="reject" data-i="${i}" data-a="reject">Verwerfen</button></div>`).join("");
const r={not_yet:"noch im Prozess",possible:"Schwelle wird denkbar",ready:"Schwelle erscheint tragf?hig"};$("readiness").textContent=r[state.readiness]||r.not_yet;$("thresholdBtn").classList.toggle("muted-threshold",state.readiness==="not_yet");
const d=state.conversationDynamics||{},box=$("directorBox");box.classList.remove("hidden","risk");if(state.events.length>1){if(d.risk&&d.risk!=="none")box.classList.add("risk");box.innerHTML=`<strong>Gespr?chsbewegung: ${esc(moveLabels[d.next_move]||d.next_move||"offen")}</strong>${d.dominant_theme?` ? ${esc(d.dominant_theme)}`:""}<div class="small">${esc(d.note||"")}</div>${d.risk&&d.risk!=="none"?`<div class="small"><strong>Hinweis:</strong> ${esc(d.risk)}</div>`:""}<div class="move-actions"><button data-move="differentiate">Unterscheiden</button><button data-move="contrast">Kontrast</button><button data-move="condense">Verdichten</button><button data-move="resource">Ressourcen</button></div>`}else box.classList.add("hidden");
if(state.suggestion){$("suggestionBox").classList.remove("hidden");$("suggestionBox").innerHTML=`<strong>${esc(labels[state.suggestion.id]||"Perspektive")} k?nnte hilfreich sein.</strong><br>${esc(state.suggestion.reason||"")}<br><button data-suggested="${esc(state.suggestion.id)}">Einladen</button>`}else $("suggestionBox").classList.add("hidden");
$("loading").classList.toggle("hidden",!busy);document.querySelectorAll("button").forEach(b=>b.disabled=busy);save()}
async function callThink(role,currentInput="",forcedMove=null){busy=true;clearError();render();try{const response=await fetch("/api/think",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({role,startingPoint:state.startingPoint,thinkingState:state.thinkingState,conversationDynamics:state.conversationDynamics,events:state.events,currentInput,forcedMove})});const data=await response.json();if(!response.ok)throw new Error(data.detail||data.error||`HTTP ${response.status}`);const result=data.result||{};if(result.message)state.events.push({author:role,text:result.message});if(Array.isArray(result.state_candidates))state.pendingCandidates.push(...result.state_candidates.filter(c=>c&&typeToBucket[c.type]&&c.text).slice(0,2));state.suggestion=result.suggested_perspective||null;state.readiness=result.threshold_readiness||state.readiness;state.conversationDynamics=result.conversation_dynamics||state.conversationDynamics}catch(e){showError(e.message||String(e))}finally{busy=false;render()}}
$("startBtn").onclick=async()=>{if(busy)return;const text=$("startInput").value.trim();if(!text)return;state.startingPoint=text;state.events.push({author:"human",text});render();await callThink("companion",text)};
$("sendBtn").onclick=async()=>{if(busy)return;const text=$("messageInput").value.trim();if(!text)return;$("messageInput").value="";state.events.push({author:"human",text});state.suggestion=null;render();await callThink("companion",text)};
$("perspectiveToggle").onclick=()=>$("perspectivePicker").classList.toggle("hidden");
$("perspectivePicker").onclick=async e=>{const b=e.target.closest("button[data-role]");if(!b||busy)return;$("perspectivePicker").classList.add("hidden");await callThink(b.dataset.role)};
$("suggestionBox").onclick=async e=>{const b=e.target.closest("button[data-suggested]");if(!b||busy)return;state.suggestion=null;await callThink(b.dataset.suggested)};
$("directorBox").onclick=async e=>{const b=e.target.closest("button[data-move]");if(!b||busy)return;await callThink("companion","",b.dataset.move)};
$("candidateList").onclick=e=>{const b=e.target.closest("button[data-i]");if(!b)return;const i=Number(b.dataset.i),c=state.pendingCandidates[i];if(!c)return;if(b.dataset.a==="accept"){const bucket=typeToBucket[c.type];if(bucket&&!state.thinkingState[bucket].includes(c.text))state.thinkingState[bucket].push(c.text)}state.pendingCandidates.splice(i,1);render()};
$("thresholdBtn").onclick=()=>{state.mode="threshold";const m=[...state.thinkingState.theological_tensions,...state.thinkingState.emerging_testimonies,...state.thinkingState.questions].slice(0,7);$("thresholdSummary").innerHTML=m.length?`<strong>Spuren:</strong><ul>${m.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:"Der Denkstand ist noch offen.";render()};
$("backBtn").onclick=()=>{state.mode="thinking";render()};$("snapshotBtn").onclick=()=>{state.threshold={changed:$("changedInput").value.trim(),testimony:$("testimonyInput").value.trim(),not_to_prescribe:$("openInput").value.trim(),open_conditions:$("conditionsInput").value.trim()};$("snapshot").textContent=JSON.stringify({starting_point:state.startingPoint,thinking_state:state.thinkingState,conversation_dynamics:state.conversationDynamics,threshold:state.threshold},null,2);$("snapshot").classList.remove("hidden");save()};
$("resetBtn").onclick=()=>{if(confirm("Session zur?cksetzen?")){localStorage.removeItem(STORAGE_KEY);location.reload()}};
function showError(m){$("errorBox").textContent=m;$("errorBox").classList.remove("hidden")}function clearError(){$("errorBox").classList.add("hidden")}render();